(21, 'divaconfig.uspSampleProcessData', NULL, 'CREATE PROCEDURE [divaconfig].[uspSampleProcessData]
AS
BEGIN
    -- Generate a new Execution ID
    DECLARE @ExecutionID UNIQUEIDENTIFIER = NEWID();

    -- Start logging the execution details
    EXEC [divaconfig].[uspLogCustomSP]
        @InputStoredProcedureExecutionID = @ExecutionID,
        @InputStoredProcedureName = ''uspProcessData'',
        @InputTransactionType = ''Start-INSERT'',
        @InputBatchId = 2002,
        @InputStoredProcedureParameterAll = ''ProcessType=DataLoad;RecordID=2024'',
        @ExecutionContext = ''Data load operation for records'',
        @ExecutionSqContext = 101,
        @ExecutionPipelineContext = ''ETL Pipeline Execution'',
        @AzureCorrelationId = @ExecutionID;

    -- Actual processing logic of the stored procedure (for example, a data load or some operation)
    BEGIN TRY
        -- Processing logic here
        -- Simulate a delay (can be replaced by real logic)
        WAITFOR DELAY ''00:00:10''; -- Simulates 10 seconds of processing
        
        -- Log success at the end of the operation
        EXEC [divaconfig].[uspLogCustomSP]
            @InputStoredProcedureExecutionID = @ExecutionID,
            @InputStoredProcedureName = ''uspProcessData'',
            @InputTransactionType = ''End-SUCCESS'',
            @InputBatchId = 2002,
            @InputStoredProcedureParameterAll = ''ProcessType=DataLoad;RecordID=2024'',
            @ExecutionContext = ''Data load operation for records completed'',
            @ExecutionSqContext = 101,
            @ExecutionPipelineContext = ''ETL Pipeline Execution'',
            @AzureCorrelationId = @ExecutionID;
    END TRY
    BEGIN CATCH
        -- Log the error if something goes wrong
        EXEC [divaconfig].[uspLogCustomSP]
            @InputStoredProcedureExecutionID = @ExecutionID,
            @InputStoredProcedureName = ''uspProcessData'',
            @InputTransactionType = ''End-ERROR'',
            @InputBatchId = 2002,
            @InputStoredProcedureParameterAll = ''ProcessType=DataLoad;RecordID=2024'',
            @ExecutionContext = ''Data load operation failed'',
            @ExecutionSqContext = 101,
            @ExecutionPipelineContext = ''ETL Pipeline Execution'',
            @AzureCorrelationId = @ExecutionID;
        
        -- Optionally, re-throw the error to propagate it
        THROW;
    END CATCH;
END;
', NULL, '2024-10-21 02:30:33.677000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-01-15 09:46:30.343000', NULL),
(22, 'divaconfig.uspSampleMainProcess', NULL, 'CREATE PROCEDURE [divaconfig].[uspSampleMainProcess]
AS
BEGIN
    -- Generate a new Execution ID for logging
    DECLARE @ExecutionID UNIQUEIDENTIFIER = NEWID();

    -- Start logging for the parent procedure
    EXEC [divaconfig].[uspLogCustomSP]
        @InputStoredProcedureExecutionID = @ExecutionID,
        @InputStoredProcedureName = ''uspMainProcess'',
        @InputTransactionType = ''Start-PROCESS'',
        @InputBatchId = 3003,
        @InputStoredProcedureParameterAll = ''ProcessID=3003'',
        @ExecutionContext = ''Main process initiation'',
        @ExecutionSqContext = 303,
        @ExecutionPipelineContext = ''Main Process'',
        @AzureCorrelationId = @ExecutionID;

    -- Call the child procedure that internally logs its own process
    BEGIN TRY
        -- Call the child process (e.g., uspProcessData)
        EXEC [divaconfig].[uspSampleProcessData];

        -- Log success after the child procedure finishes successfully
        EXEC [divaconfig].[uspLogCustomSP]
            @InputStoredProcedureExecutionID = @ExecutionID,
            @InputStoredProcedureName = ''uspMainProcess'',
            @InputTransactionType = ''End-SUCCESS'',
            @InputBatchId = 3003,
            @InputStoredProcedureParameterAll = ''ProcessID=3003'',
            @ExecutionContext = ''Main process completed successfully'',
            @ExecutionSqContext = 303,
            @ExecutionPipelineContext = ''Main Process'',
            @AzureCorrelationId = @ExecutionID;
    END TRY
    BEGIN CATCH
        -- Log error if something goes wrong
        EXEC [divaconfig].[uspLogCustomSP]
            @InputStoredProcedureExecutionID = @ExecutionID,
            @InputStoredProcedureName = ''uspMainProcess'',
