--Order by BusinessPartner

Select ''Final'' as ''StatusAT'',a.ConfigID, a.CompareCode,[MatchStatus],BPStatus, Count(1)  
from #DMS_FactL2Monitor a
inner join [dbo].[DMS_CustMonitorConfig] b on a.ConfigID = b.ConfigID
