( [LoadRunDateTime], [BusinessPartner], [ConfigID], [ConfigValue], [IsSAP], [IsSQL], [IsFTP], [IsSharePoint]
, [MatchStatus], [CompareCode], [CodeDescription], [BPEtEMatch], [FactL1ID], [CriteriaValue], [BRStatus], [BRIMRelevancy],BPStatus)
