(49, 'divaconfig.LoadTableInfo', NULL, 'CREATE   PROCEDURE [divaconfig].[LoadTableInfo]
AS
BEGIN
    SET NOCOUNT ON;

    -- Declare a table variable to hold the latest metadata
    DECLARE @LatestMetadata TABLE (
        ID INT IDENTITY(1,1),
        TableDatabaseName NVARCHAR(255),
        TableSchemaName NVARCHAR(255),
        TableName NVARCHAR(255),
        TableDescription NVARCHAR(MAX),
        TableRowCount BIGINT NULL,
        TableColumnCount INT,
        TableIdentityColumnName NVARCHAR(255),
        TablePrimaryColumnCSV NVARCHAR(MAX),
        TableUniqueColumnCSV NVARCHAR(MAX),
        IsTableEditable BIT,
        TableMetadataSyncDateTime DATETIME
    );

    -- Insert latest metadata into the table variable
    INSERT INTO @LatestMetadata
    SELECT 
        DB_NAME() AS TableDatabaseName,              -- Current database name
        t.TABLE_SCHEMA AS TableSchemaName,          -- Schema of the table
        t.TABLE_NAME AS TableName,                  -- Name of the table
        ''Table name is '' + t.TABLE_NAME AS TableDescription, -- Table description
        NULL AS TableRowCount,                      -- Placeholder for row count
        COUNT(c.COLUMN_NAME) AS TableColumnCount,   -- Total column count
        NULL AS TableIdentityColumnName,            -- Identity column (not available in INFORMATION_SCHEMA)
        STRING_AGG(pk.COLUMN_NAME, '','') AS TablePrimaryColumnCSV, -- Primary key columns (comma-separated)
        STRING_AGG(u.COLUMN_NAME, '','') AS TableUniqueColumnCSV,   -- Unique key columns (comma-separated)
        CASE 
            WHEN t.TABLE_TYPE = ''BASE TABLE'' THEN 1 -- Editable for base tables
            ELSE 0
        END AS IsTableEditable, 
        GETDATE() AS TableMetadataSyncDateTime      -- Current date for metadata sync
    FROM 
        INFORMATION_SCHEMA.TABLES t
    LEFT JOIN 
        INFORMATION_SCHEMA.COLUMNS c 
        ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
    LEFT JOIN 
        (SELECT 
             ku.TABLE_SCHEMA, 
             ku.TABLE_NAME, 
             ku.COLUMN_NAME
         FROM 
             INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
         JOIN 
             INFORMATION_SCHEMA.KEY_COLUMN_USAGE ku
             ON tc.CONSTRAINT_NAME = ku.CONSTRAINT_NAME
         WHERE 
             tc.CONSTRAINT_TYPE = ''PRIMARY KEY'') pk
        ON t.TABLE_SCHEMA = pk.TABLE_SCHEMA AND t.TABLE_NAME = pk.TABLE_NAME
    LEFT JOIN 
        (SELECT 
             ku.TABLE_SCHEMA, 
             ku.TABLE_NAME, 
             ku.COLUMN_NAME
         FROM 
             INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
         JOIN 
             INFORMATION_SCHEMA.KEY_COLUMN_USAGE ku
             ON tc.CONSTRAINT_NAME = ku.CONSTRAINT_NAME
         WHERE 
             tc.CONSTRAINT_TYPE = ''UNIQUE'') u
        ON t.TABLE_SCHEMA = u.TABLE_SCHEMA AND t.TABLE_NAME = u.TABLE_NAME
    WHERE 
        t.TABLE_TYPE IN (''BASE TABLE'') -- Include only base tables
    GROUP BY 
        t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_TYPE;

    -- Variables for row count updates
    DECLARE @ID INT, @MaxID INT, @SchemaName NVARCHAR(255), @TableName NVARCHAR(255), @SQL NVARCHAR(MAX), @RowCount BIGINT;

    -- Get the range of IDs in the table
    SELECT @ID = MIN(ID), @MaxID = MAX(ID) FROM @LatestMetadata;

    -- WHILE loop to process each table
    WHILE @ID IS NOT NULL AND @ID <= @MaxID
    BEGIN
        -- Get the schema and table name for the current record
        SELECT @SchemaName = TableSchemaName, @TableName = TableName
        FROM @LatestMetadata WHERE ID = @ID;

        -- Build dynamic SQL to get the row count
        SET @SQL = N''SELECT @RowCount = COUNT(*) FROM ['' + @SchemaName + ''].['' + @TableName + '']'';

        BEGIN TRY
            -- Execute the SQL and get the row count
            EXEC sp_executesql @SQL, N''@RowCount BIGINT OUTPUT'', @RowCount OUTPUT;

            -- Update the row count in @LatestMetadata
            UPDATE @LatestMetadata
            SET TableRowCount = @RowCount
            WHERE ID = @ID;
        END TRY
        BEGIN CATCH
            -- Log errors if any during row count execution
            PRINT ''Error calculating row count for ['' + @SchemaName + ''].['' + @TableName + '']: '' 
                + ERROR_MESSAGE();
        END CATCH;

        -- Increment to the next record
        SET @ID = @ID + 1;
    END;

    -- Insert new records
    INSERT INTO [divaconfig].[TableInfo] (
        TableDatabaseName,
        TableSchemaName,
        TableName,
        TableDescription,
        TableRowCount,
        TableColumnCount,
        TableIdentityColumnName,
        TablePrimaryColumnCSV,
        TableUniqueColumnCSV,
        IsTableEditable,
        TableMetadataSyncDateTime,
        IsDeleted
    )
    SELECT 
        lm.TableDatabaseName,
        lm.TableSchemaName,
        lm.TableName,
        lm.TableDescription,
        lm.TableRowCount,
        lm.TableColumnCount,
        lm.TableIdentityColumnName,
        lm.TablePrimaryColumnCSV,
        lm.TableUniqueColumnCSV,
        lm.IsTableEditable,
        lm.TableMetadataSyncDateTime,
        0 -- IsDeleted = 0 for new records
    FROM 
        @LatestMetadata lm
    WHERE 
        NOT EXISTS (
            SELECT 1 
            FROM [divaconfig].[TableInfo] ti
            WHERE ti.TableDatabaseName = lm.TableDatabaseName
              AND ti.TableSchemaName = lm.TableSchemaName
              AND ti.TableName = lm.TableName
        );

    -- Update existing records
    UPDATE ti
    SET 
        ti.TableDescription = lm.TableDescription,
        ti.TableRowCount = lm.TableRowCount,
        ti.TableColumnCount = lm.TableColumnCount,
        ti.TableIdentityColumnName = lm.TableIdentityColumnName,
        ti.TablePrimaryColumnCSV = lm.TablePrimaryColumnCSV,
        ti.TableUniqueColumnCSV = lm.TableUniqueColumnCSV,
        ti.IsTableEditable = lm.IsTableEditable,
        ti.TableMetadataSyncDateTime = lm.TableMetadataSyncDateTime,
        ti.IsDeleted = 0, -- Reset IsDeleted flag if it was previously set
        ti.UpdatedAt = GETDATE()
    FROM 
        [divaconfig].[TableInfo] ti
    INNER JOIN 
        @LatestMetadata lm
    ON 
        ti.TableDatabaseName = lm.TableDatabaseName
        AND ti.TableSchemaName = lm.TableSchemaName
        AND ti.TableName = lm.TableName;

    -- Soft delete records not in the latest metadata
    UPDATE ti
    SET 
        ti.IsDeleted = 1,
        ti.UpdatedAt = GETDATE()
    FROM 
        [divaconfig].[TableInfo] ti
    WHERE 
        NOT EXISTS (
            SELECT 1 
            FROM @LatestMetadata lm
            WHERE ti.TableDatabaseName = lm.TableDatabaseName
              AND ti.TableSchemaName = lm.TableSchemaName
              AND ti.TableName = lm.TableName
        );

    SET NOCOUNT OFF;
END;
', NULL, '2024-12-22 03:12:15.110000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 03:47:42.367000', NULL),
(50, 'divaconfig.loadSpecialTableCardChart', NULL, 'CREATE proc divaconfig.loadSpecialTableCardChart
AS


MERGE INTO [divaconfig].[CardDisplayPerSubtab] AS target
USING (
    SELECT 
        84 AS SubTabID,
        DimTableName AS ChartDisplayName,
        CAST(DimTableLastUpdated AS DATE) AS ChartDisplayValue,
        ''Build on '' AS ChartDisplayValuePrefix,
        '' Date'' AS ChartDisplayValueSuffix,
        ''Value Generated for '' + DimTableName + '' '' + DimTableDescription AS ChartDisplayDescription
    FROM divadim.DimMaster
) AS source
ON target.ChartDisplayName = source.ChartDisplayName  -- Matching based on ChartDisplayName

WHEN MATCHED THEN
    UPDATE SET 
        ChartDisplayValue = source.ChartDisplayValue,
        ChartDisplayValuePrefix = source.ChartDisplayValuePrefix,
        ChartDisplayValueSuffix = source.ChartDisplayValueSuffix,
        ChartDisplayDescription = source.ChartDisplayDescription

WHEN NOT MATCHED THEN
    INSERT (SubTabID, ChartDisplayName, ChartDisplayValue, ChartDisplayValuePrefix, ChartDisplayValueSuffix, ChartDisplayDescription)
    VALUES (source.SubTabID, source.ChartDisplayName, source.ChartDisplayValue, source.ChartDisplayValuePrefix, source.ChartDisplayValueSuffix, source.ChartDisplayDescription);
', NULL, '2025-02-07 03:42:53.477000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 03:47:42.367000', NULL),
(51, 'dbo.PopulateDateDimension', NULL, '
CREATE   PROCEDURE PopulateDateDimension
    @StartDate DATE = ''20240101'',
    @NumberOfYears INT = 2
AS
--exec PopulateDateDimension ''20250101'',1
 --Declare   @StartDate DATE = ''20250101'',
 --   @NumberOfYears INT = 1
    -- Set consistent settings
    SET DATEFIRST 7;
    SET DATEFORMAT mdy;
    SET LANGUAGE us_english;

	DELETE FROM divadim.DateDimension
	WHERE  [Year] = YEAR(@StartDate);


    -- Calculate the cutoff date
    DECLARE @CutoffDate DATE = DATEADD(YEAR, @NumberOfYears, @StartDate);

    -- Drop and recreate the DateDimension table
    IF OBJECT_ID(''divadim.DateDimension'', ''U'') IS NOT NULL
        DROP TABLE divadim.DateDimension;

    CREATE TABLE divadim.DateDimension
    (
        DateKey             INT         NOT NULL PRIMARY KEY,
        [Date]              DATE        NOT NULL,
        [Day]               TINYINT     NOT NULL,
        DaySuffix           CHAR(2)     NOT NULL,
        [Weekday]           TINYINT     NOT NULL,
        WeekDayName         VARCHAR(10) NOT NULL,
        WeekdayAbbreviation CHAR(3)     NOT NULL,
        IsWeekend           BIT         NOT NULL,
        IsHoliday           BIT         DEFAULT 0 NOT NULL,
        HolidayText         VARCHAR(64) SPARSE,
        FiscalYear          INT         NOT NULL,
        FiscalQuarter       TINYINT     NOT NULL,
        HalfYear            TINYINT     NOT NULL,
        Season              VARCHAR(10) NOT NULL,
        WeekOfYear          TINYINT     NOT NULL,
        [Month]             TINYINT     NOT NULL,
        [MonthName]         VARCHAR(10) NOT NULL,
        [Quarter]           TINYINT     NOT NULL,
        [Year]              INT         NOT NULL,
        FirstDayOfMonth     DATE        NOT NULL,
        LastDayOfMonth      DATE        NOT NULL
    );

    -- Populate the DateDimension table using a WHILE loop
    DECLARE @CurrentDate DATE = @StartDate;

    WHILE @CurrentDate < @CutoffDate
    BEGIN
        INSERT INTO divadim.DateDimension
        (
            DateKey,
            [Date],
            [Day],
            DaySuffix,
            [Weekday],
            WeekDayName,
            WeekdayAbbreviation,
            IsWeekend,
            FiscalYear,
            FiscalQuarter,
            HalfYear,
            Season,
            WeekOfYear,
            [Month],
            [MonthName],
            [Quarter],
            [Year],
            FirstDayOfMonth,
            LastDayOfMonth
        )
        SELECT
            DateKey       = CONVERT(INT, CONVERT(CHAR(8), @CurrentDate, 112)),
            [Date]        = @CurrentDate,
            [Day]         = DAY(@CurrentDate),
            DaySuffix     = CASE 
                              WHEN DAY(@CurrentDate) IN (1, 21, 31) THEN ''st''
                              WHEN DAY(@CurrentDate) IN (2, 22) THEN ''nd''
                              WHEN DAY(@CurrentDate) IN (3, 23) THEN ''rd''
                              ELSE ''th'' END,
            [Weekday]     = DATEPART(WEEKDAY, @CurrentDate),
            WeekDayName   = DATENAME(WEEKDAY, @CurrentDate),
            WeekdayAbbreviation = LEFT(DATENAME(WEEKDAY, @CurrentDate), 3),
            IsWeekend     = CASE WHEN DATEPART(WEEKDAY, @CurrentDate) IN (1, 7) THEN 1 ELSE 0 END,
            FiscalYear    = YEAR(@CurrentDate), -- Adjust if fiscal year differs
            FiscalQuarter = DATEPART(QUARTER, @CurrentDate),
            HalfYear      = CASE WHEN MONTH(@CurrentDate) <= 6 THEN 1 ELSE 2 END,
            Season        = CASE 
                              WHEN MONTH(@CurrentDate) IN (12, 1, 2) THEN ''Winter''
                              WHEN MONTH(@CurrentDate) IN (3, 4, 5) THEN ''Spring''
                              WHEN MONTH(@CurrentDate) IN (6, 7, 8) THEN ''Summer''
                              WHEN MONTH(@CurrentDate) IN (9, 10, 11) THEN ''Autumn'' END,
            WeekOfYear    = DATEPART(WEEK, @CurrentDate),
            [Month]       = MONTH(@CurrentDate),
            [MonthName]   = DATENAME(MONTH, @CurrentDate),
            [Quarter]     = DATEPART(QUARTER, @CurrentDate),
            [Year]        = YEAR(@CurrentDate),
            FirstDayOfMonth = DATEADD(MONTH, DATEDIFF(MONTH, 0, @CurrentDate), 0),
            LastDayOfMonth  = EOMONTH(@CurrentDate);

        SET @CurrentDate = DATEADD(DAY, 1, @CurrentDate);
    END;

    -- Populate IsHoliday and HolidayText
    UPDATE divadim.DateDimension
    SET IsHoliday = 1, HolidayText = ''New Year''''s Day''
    WHERE MONTH([Date]) = 1 AND DAY([Date]) = 1;



	--Select * from divadim.DateDimension ', NULL, '2025-01-10 06:05:08.763000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 03:47:42.367000', NULL),
(52, 'divadim.LoadDateDimension', NULL, '
CREATE PROCEDURE divadim.LoadDateDimension
    @StartDate DATE = ''20250101'',
    @NumberOfYears INT = 1
AS
--exec divadim.LoadDateDimension ''20200101'',10
 --Declare   @StartDate DATE = ''20250101'',
 --   @NumberOfYears INT = 1
    -- Set consistent settings
    SET DATEFIRST 7;
    SET DATEFORMAT mdy;
    SET LANGUAGE us_english;

	DELETE FROM divadim.DateDimension
	WHERE  [Year] = YEAR(@StartDate);


    -- Calculate the cutoff date
    DECLARE @CutoffDate DATE = DATEADD(YEAR, @NumberOfYears, @StartDate);

    -- Drop and recreate the DateDimension table
    IF OBJECT_ID(''divadim.DateDimension'', ''U'') IS NOT NULL
        DROP TABLE divadim.DateDimension;

    CREATE TABLE divadim.DateDimension
    (
        DateKey             INT         NOT NULL PRIMARY KEY,
        [Date]              DATE        NOT NULL,
        [Day]               TINYINT     NOT NULL,
        DaySuffix           CHAR(2)     NOT NULL,
        [Weekday]           TINYINT     NOT NULL,
        WeekDayName         VARCHAR(10) NOT NULL,
        WeekdayAbbreviation CHAR(3)     NOT NULL,
        IsWeekend           BIT         NOT NULL,
        IsHoliday           BIT         DEFAULT 0 NOT NULL,
        HolidayText         VARCHAR(64) SPARSE,
        FiscalYear          INT         NOT NULL,
        FiscalQuarter       TINYINT     NOT NULL,
        HalfYear            TINYINT     NOT NULL,
        Season              VARCHAR(10) NOT NULL,
        WeekOfYear          TINYINT     NOT NULL,
        [Month]             TINYINT     NOT NULL,
        [MonthName]         VARCHAR(10) NOT NULL,
        [Quarter]           TINYINT     NOT NULL,
        [Year]              INT         NOT NULL,
        FirstDayOfMonth     DATE        NOT NULL,
        LastDayOfMonth      DATE        NOT NULL
    );

    -- Populate the DateDimension table using a WHILE loop
    DECLARE @CurrentDate DATE = @StartDate;

    WHILE @CurrentDate < @CutoffDate
    BEGIN
        INSERT INTO divadim.DateDimension
        (
            DateKey,
            [Date],
            [Day],
            DaySuffix,
            [Weekday],
            WeekDayName,
            WeekdayAbbreviation,
            IsWeekend,
            FiscalYear,
            FiscalQuarter,
            HalfYear,
            Season,
            WeekOfYear,
            [Month],
            [MonthName],
            [Quarter],
            [Year],
            FirstDayOfMonth,
            LastDayOfMonth
        )
        SELECT
            DateKey       = CONVERT(INT, CONVERT(CHAR(8), @CurrentDate, 112)),
            [Date]        = @CurrentDate,
            [Day]         = DAY(@CurrentDate),
            DaySuffix     = CASE 
                              WHEN DAY(@CurrentDate) IN (1, 21, 31) THEN ''st''
                              WHEN DAY(@CurrentDate) IN (2, 22) THEN ''nd''
                              WHEN DAY(@CurrentDate) IN (3, 23) THEN ''rd''
                              ELSE ''th'' END,
            [Weekday]     = DATEPART(WEEKDAY, @CurrentDate),
            WeekDayName   = DATENAME(WEEKDAY, @CurrentDate),
            WeekdayAbbreviation = LEFT(DATENAME(WEEKDAY, @CurrentDate), 3),
            IsWeekend     = CASE WHEN DATEPART(WEEKDAY, @CurrentDate) IN (1, 7) THEN 1 ELSE 0 END,
            FiscalYear    = YEAR(@CurrentDate), -- Adjust if fiscal year differs
            FiscalQuarter = DATEPART(QUARTER, @CurrentDate),
            HalfYear      = CASE WHEN MONTH(@CurrentDate) <= 6 THEN 1 ELSE 2 END,
            Season        = CASE 
                              WHEN MONTH(@CurrentDate) IN (12, 1, 2) THEN ''Winter''
                              WHEN MONTH(@CurrentDate) IN (3, 4, 5) THEN ''Spring''
                              WHEN MONTH(@CurrentDate) IN (6, 7, 8) THEN ''Summer''
                              WHEN MONTH(@CurrentDate) IN (9, 10, 11) THEN ''Autumn'' END,
            WeekOfYear    = DATEPART(WEEK, @CurrentDate),
            [Month]       = MONTH(@CurrentDate),
            [MonthName]   = DATENAME(MONTH, @CurrentDate),
            [Quarter]     = DATEPART(QUARTER, @CurrentDate),
            [Year]        = YEAR(@CurrentDate),
            FirstDayOfMonth = DATEADD(MONTH, DATEDIFF(MONTH, 0, @CurrentDate), 0),
            LastDayOfMonth  = EOMONTH(@CurrentDate);

        SET @CurrentDate = DATEADD(DAY, 1, @CurrentDate);
    END;

    -- Populate IsHoliday and HolidayText
    UPDATE divadim.DateDimension
    SET IsHoliday = 1, HolidayText = ''New Year''''s Day''
    WHERE MONTH([Date]) = 1 AND DAY([Date]) = 1;



	--Select * from divadim.DateDimension ', NULL, '2025-01-10 06:07:24.537000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 03:47:42.367000', NULL),
(53, 'divaconfig.LoadColumnInfo', NULL, 'CREATE PROCEDURE [divaconfig].[LoadColumnInfo]
AS

--    SET NOCOUNT ON;

    -- Declare a table variable to hold the latest metadata

-- Drop the table if it exists
IF OBJECT_ID(''dbo.DivaTempLatestMetadata'', ''U'') IS NOT NULL
    DROP TABLE dbo.DivaTempLatestMetadata;

-- Use SELECT INTO to dynamically create the table with all data types
SELECT TOP 0 *
INTO dbo.DivaTempLatestMetadata
FROM divaconfig.ColumnInfo;

    -- Populate metadata for columns
    INSERT INTO DivaTempLatestMetadata
	(DatabaseName, SchemaName, TableName, ColumnName, ColumnSort, ColumnDescription, DataType, MaxLengthOrValue, MinLengthOrValue, 
    DefaultValue, ValidationRules, CustomCastForSearch, CustomCastForCRUD, DistinctValueCount, IsNullable, IsPrimaryKey, 
    IsForeignKey, IsLookupValue, IsEditable, IsFixedSetValue, IsDate, IsTime, IsDateTime, IsIdentity, IsInt, IsFloat, 
    IsAssociatedToDelete, IsDeleted, IsVoid, IsSensitive, IsUpdateAllow, DataClassification, ComplianceTag, QualityScore, 
    QualityRemarks, ParentColumnID, RestrictionsType, ColumnMetadataSyncDateTime, CreatedAt, UpdatedAt, UpdatedBy,IsDelta,IsLockFromBackend,IsLockFromFrontEnd
)
    SELECT 
        DB_NAME() AS DatabaseName,
        c.TABLE_SCHEMA AS SchemaName,
        c.TABLE_NAME AS TableName,
        c.COLUMN_NAME AS ColumnName,
        c.ORDINAL_POSITION AS ColumnSort, -- Placeholder
        NULL AS ColumnDescription,
        c.DATA_TYPE AS DataType,
        CASE WHEN c.CHARACTER_MAXIMUM_LENGTH = -1 THEN NULL ELSE c.CHARACTER_MAXIMUM_LENGTH END AS MaxLengthOrValue,
        NULL AS MinLengthOrValue, 
        c.COLUMN_DEFAULT AS DefaultValue,
        NULL AS ValidationRules,
        ''CAST(['' + c.COLUMN_NAME + ''] AS NVARCHAR(MAX))'' AS CustomCastForSearch,
            CASE 
        WHEN  c.DATA_TYPE = ''INT'' THEN ''CAST('' + c.COLUMN_NAME + '' AS INT)''
        WHEN  c.DATA_TYPE = ''DECIMAL'' THEN ''CAST('' + c.COLUMN_NAME + '' AS DECIMAL(18, 2))''
        WHEN  c.DATA_TYPE = ''DATETIME'' THEN ''CAST('' + c.COLUMN_NAME + '' AS DATETIME)''
        WHEN  c.DATA_TYPE = ''BIT'' THEN ''CAST('' + c.COLUMN_NAME + '' AS BIT)''
        WHEN  c.DATA_TYPE = ''VARCHAR'' THEN ''CAST('' + c.COLUMN_NAME + '' AS VARCHAR(MAX))''
        WHEN  c.DATA_TYPE = ''FLOAT'' THEN ''CAST('' + c.COLUMN_NAME + '' AS FLOAT)''
        WHEN  c.DATA_TYPE = ''TIME'' THEN ''CAST('' + c.COLUMN_NAME + '' AS TIME)''
        WHEN  c.DATA_TYPE = ''DATE'' THEN ''CAST('' + c.COLUMN_NAME + '' AS DATE)''
		WHEN  c.DATA_TYPE = ''nvarchar'' THEN ''CAST('' + c.COLUMN_NAME + '' AS nvarchar(MAX))''
        ELSE null 
		 END AS  CustomCastForCRUD,
        NULL AS DistinctValueCount,
        CASE WHEN c.IS_NULLABLE = ''YES'' THEN 1 ELSE 0 END AS IsNullable,
        CASE WHEN pk.COLUMN_NAME IS NOT NULL THEN 1 ELSE 0 END AS IsPrimaryKey,
        0 AS IsForeignKey,
        0 AS IsLookupValue,
        1 AS IsEditable,
        0 AS IsFixedSetValue,
        CASE WHEN c.DATA_TYPE IN (''date'') THEN 1 ELSE 0 END AS IsDate,
        CASE WHEN c.DATA_TYPE IN (''time'') THEN 1 ELSE 0 END AS IsTime,
        CASE WHEN c.DATA_TYPE IN (''datetime'', ''smalldatetime'') THEN 1 ELSE 0 END AS IsDateTime,
        Case WHEN id.IsIdentity is null then 0 else id.IsIdentity end AS IsIdentity, -- Placeholder
        CASE WHEN c.DATA_TYPE IN (''int'', ''bigint'', ''smallint'', ''tinyint'') THEN 1 ELSE 0 END AS IsInt,
        CASE WHEN c.DATA_TYPE IN (''float'', ''real'', ''decimal'', ''numeric'') THEN 1 ELSE 0 END AS IsFloat,
        CASE WHEN pk.COLUMN_NAME IS NOT NULL THEN 0 ELSE 1 END AS IsAssociatedToDelete,
        0 AS IsDeleted,
        0 AS IsVoid,
        0 AS IsSensitive,
        0 AS IsUpdateAllow,
        NULL AS DataClassification,
        NULL AS ComplianceTag,
        NULL AS QualityScore,
        NULL AS QualityRemarks,
        NULL AS ParentColumnID,
        NULL AS RestrictionsType,
        GETDATE() AS ColumnMetadataSyncDateTime,
        GETDATE() AS CreatedAt,
        GETDATE() AS UpdatedAt,
        NULL AS UpdatedBy,
		0 AS IsDelta,
		0 AS IsLockFromBackend,
		0 AS IsLockFromFrontEnd
    FROM INFORMATION_SCHEMA.COLUMNS c
    LEFT JOIN (
        SELECT 
            ku.TABLE_SCHEMA, 
            ku.TABLE_NAME, 
            ku.COLUMN_NAME
        FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
        JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE ku
            ON tc.CONSTRAINT_NAME = ku.CONSTRAINT_NAME
        WHERE tc.CONSTRAINT_TYPE = ''PRIMARY KEY''
    ) pk
        ON c.TABLE_SCHEMA = pk.TABLE_SCHEMA 
        AND c.TABLE_NAME = pk.TABLE_NAME 
        AND c.COLUMN_NAME = pk.COLUMN_NAME
    LEFT JOIN (SELECT 
		c.TABLE_SCHEMA,
		c.TABLE_NAME,
		c.COLUMN_NAME,
		c.ORDINAL_POSITION,
		CASE 
			WHEN COLUMNPROPERTY(OBJECT_ID(c.TABLE_SCHEMA + ''.'' + c.TABLE_NAME), c.COLUMN_NAME, ''IsIdentity'') = 1 THEN 1 
			ELSE 0 
		END AS IsIdentity
	FROM INFORMATION_SCHEMA.COLUMNS c
	) id 
		 ON id.TABLE_SCHEMA = pk.TABLE_SCHEMA 
        AND id.TABLE_NAME = pk.TABLE_NAME 
        AND id.COLUMN_NAME = pk.COLUMN_NAME


-----------------C1
DECLARE @SQL NVARCHAR(MAX), @DistinctCount BIGINT;
DECLARE @DynamicSQL NVARCHAR(MAX);
DECLARE @CurrentIndex INT = 1;
DECLARE @TotalColumns INT;

-- Get the total number of columns to process
SELECT @TotalColumns = COUNT(*) FROM DivaTempLatestMetadata;

-- Temporary table to store intermediate results
IF OBJECT_ID(''dbo.DivaTempDistinctCounts'', ''U'') IS NOT NULL
    DROP TABLE dbo.DivaTempDistinctCounts;
CREATE TABLE dbo.DivaTempDistinctCounts (
    DistinctValueCount BIGINT,
    SchemaName NVARCHAR(128),
    TableName NVARCHAR(128),
    ColumnName NVARCHAR(128),
    MaxLengthOrValue NVARCHAR(MAX),
    MinLengthOrValue NVARCHAR(MAX),
    QualityCheckAllNullVoidOneMany NVARCHAR(50),
    QualityCheckAllNullVoidOneValue NVARCHAR(MAX)
);

-- Process each column one at a time using a WHILE loop
WHILE @CurrentIndex <= @TotalColumns
BEGIN
    -- Get the current column details
    DECLARE @SchemaName NVARCHAR(128), @TableName NVARCHAR(128), @ColumnName NVARCHAR(128), @DataType NVARCHAR(50);
    SELECT @SchemaName = SchemaName, @TableName = TableName, @ColumnName = ColumnName, @DataType = DataType
    FROM (
        SELECT *, ROW_NUMBER() OVER (ORDER BY SchemaName, TableName, ColumnName) AS RowNum
        FROM DivaTempLatestMetadata
    ) AS OrderedColumns
    WHERE RowNum = @CurrentIndex;

    -- Build dynamic SQL for the current column
    IF @DataType LIKE ''%bit%''
    BEGIN
        SET @DynamicSQL = ''
            INSERT INTO dbo.DivaTempDistinctCounts (
                DistinctValueCount, SchemaName, TableName, ColumnName, MaxLengthOrValue, MinLengthOrValue, QualityCheckAllNullVoidOneMany, QualityCheckAllNullVoidOneValue)
            SELECT 
                COUNT(DISTINCT ['' + @ColumnName + '']) AS DistinctValueCount, 
                '''''' + @SchemaName + '''''',
                '''''' + @TableName + '''''',
                '''''' + @ColumnName + '''''',
                NULL AS MaxLengthOrValue, -- Not applicable for bit
                NULL AS MinLengthOrValue, -- Not applicable for bit
                CASE 
                    WHEN COUNT(*) = SUM(CASE WHEN ['' + @ColumnName + ''] IS NULL THEN 1 ELSE 0 END) THEN ''''All NULL''''
                    WHEN COUNT(DISTINCT ['' + @ColumnName + '']) = 1 THEN ''''All ONE''''
                    ELSE ''''Many''''
                END AS QualityCheckAllNullVoidOneMany,
                CASE 
                    WHEN COUNT(*) = SUM(CASE WHEN ['' + @ColumnName + ''] IS NULL THEN 1 ELSE 0 END) THEN NULL
                    WHEN COUNT(DISTINCT ['' + @ColumnName + '']) = 1 THEN CAST(COUNT(['' + @ColumnName + '']) AS NVARCHAR)
                    ELSE NULL
                END AS QualityCheckAllNullVoidOneValue
            FROM ['' + @SchemaName + ''].['' + @TableName + '']'';
    END
    ELSE
    BEGIN
        SET @DynamicSQL = ''
            INSERT INTO dbo.DivaTempDistinctCounts (
                DistinctValueCount, SchemaName, TableName, ColumnName, MaxLengthOrValue, MinLengthOrValue, QualityCheckAllNullVoidOneMany, QualityCheckAllNullVoidOneValue)
            SELECT 
                COUNT(DISTINCT ['' + @ColumnName + '']) AS DistinctValueCount, 
                '''''' + @SchemaName + '''''',
                '''''' + @TableName + '''''',
                '''''' + @ColumnName + '''''',
                '' + CASE 
                    WHEN @DataType LIKE ''%char%'' OR @DataType LIKE ''%text%'' THEN 
                        ''MAX(LEN(['' + @ColumnName + ''])) AS MaxLengthOrValue, MIN(LEN(['' + @ColumnName + ''])) AS MinLengthOrValue''
                    WHEN @DataType LIKE ''%int%'' OR @DataType LIKE ''%numeric%'' OR @DataType LIKE ''%decimal%'' THEN 
                        ''MAX(['' + @ColumnName + '']) AS MaxLengthOrValue, MIN(['' + @ColumnName + '']) AS MinLengthOrValue''
                    WHEN @DataType LIKE ''%date%'' OR @DataType LIKE ''%time%'' THEN 
                        ''MAX(['' + @ColumnName + '']) AS MaxLengthOrValue, MIN(['' + @ColumnName + '']) AS MinLengthOrValue''
                    ELSE 
                        ''NULL AS MaxLengthOrValue, NULL AS MinLengthOrValue''
                  END + '',
                CASE 
                    WHEN COUNT(*) = SUM(CASE WHEN ['' + @ColumnName + ''] IS NULL THEN 1 ELSE 0 END) THEN ''''All NULL''''
                    WHEN COUNT(*) = SUM(CASE WHEN LTRIM(RTRIM(['' + @ColumnName + ''])) = '''''''' THEN 1 ELSE 0 END) THEN ''''All Void''''
                    WHEN COUNT(DISTINCT ['' + @ColumnName + '']) = 1 THEN ''''All ONE''''
                    ELSE ''''Many''''
                END AS QualityCheckAllNullVoidOneMany,
                CASE 
                    WHEN COUNT(*) = SUM(CASE WHEN ['' + @ColumnName + ''] IS NULL THEN 1 ELSE 0 END) THEN NULL
                    WHEN COUNT(*) = SUM(CASE WHEN LTRIM(RTRIM(['' + @ColumnName + ''])) = '''''''' THEN 1 ELSE 0 END) THEN ''''''''
                    WHEN COUNT(DISTINCT ['' + @ColumnName + '']) = 1 THEN MAX(['' + @ColumnName + ''])
                    ELSE NULL
                END AS QualityCheckAllNullVoidOneValue
            FROM ['' + @SchemaName + ''].['' + @TableName + '']'';
    END

    -- Execute the dynamic SQL
    EXEC sp_executesql @DynamicSQL;

    SET @CurrentIndex = @CurrentIndex + 1;
END

-- Update the main table with the results
UPDATE lm
SET lm.DistinctValueCount = t.DistinctValueCount,
    lm.MaxLengthOrValue = t.MaxLengthOrValue,
    lm.MinLengthOrValue = t.MinLengthOrValue,
    lm.QualityCheckAllNullVoidOneMany = t.QualityCheckAllNullVoidOneMany,
    lm.QualityCheckAllNullVoidOneValue = t.QualityCheckAllNullVoidOneValue
FROM DivaTempLatestMetadata lm
JOIN dbo.DivaTempDistinctCounts t
ON lm.SchemaName = t.SchemaName
   AND lm.TableName = t.TableName
   AND lm.ColumnName = t.ColumnName;






-----------------C1 end
Delete From [divaconfig].[ColumnInfo]

    -- Insert or update [divaconfig].[ColumnInfo]
MERGE [divaconfig].[ColumnInfo] AS ci
USING DivaTempLatestMetadata AS lm
ON ci.DatabaseName = lm.DatabaseName
    AND ci.SchemaName = lm.SchemaName
    AND ci.TableName = lm.TableName
    AND ci.ColumnName = lm.ColumnName
WHEN MATCHED AND ci.IsLockFromBackend = 0 THEN
    UPDATE SET
        ci.ColumnSort = lm.ColumnSort,
        ci.ColumnDescription = lm.ColumnDescription,
        ci.DataType = lm.DataType,
        ci.MaxLengthOrValue = lm.MaxLengthOrValue,
        ci.MinLengthOrValue = lm.MinLengthOrValue,
        ci.DefaultValue = lm.DefaultValue,
        ci.ValidationRules = lm.ValidationRules,
        ci.CustomCastForSearch = lm.CustomCastForSearch,
        ci.CustomCastForCRUD = lm.CustomCastForCRUD,
        ci.DistinctValueCount = lm.DistinctValueCount,
        ci.IsNullable = lm.IsNullable,
        ci.IsPrimaryKey = lm.IsPrimaryKey,
        ci.IsForeignKey = lm.IsForeignKey,
        ci.IsLookupValue = lm.IsLookupValue,
        ci.IsEditable = lm.IsEditable,
        ci.IsFixedSetValue = lm.IsFixedSetValue,
        ci.IsDate = lm.IsDate,
        ci.IsTime = lm.IsTime,
        ci.IsDateTime = lm.IsDateTime,
        ci.IsIdentity = lm.IsIdentity,
        ci.IsInt = lm.IsInt,
        ci.IsFloat = lm.IsFloat,
        ci.IsAssociatedToDelete = lm.IsAssociatedToDelete,
        ci.IsDeleted = lm.IsDeleted,
        ci.IsVoid = lm.IsVoid,
        ci.IsSensitive = lm.IsSensitive,
        ci.IsUpdateAllow = lm.IsUpdateAllow,
        ci.DataClassification = lm.DataClassification,
        ci.ComplianceTag = lm.ComplianceTag,
        ci.QualityScore = lm.QualityScore,
        ci.QualityRemarks = lm.QualityRemarks,
        ci.ParentColumnID = lm.ParentColumnID,
        ci.RestrictionsType = lm.RestrictionsType,
        ci.ColumnMetadataSyncDateTime = lm.ColumnMetadataSyncDateTime,
        ci.UpdatedAt = GETDATE(),
        ci.UpdatedBy = lm.UpdatedBy,
        ci.IsDelta = lm.IsDelta,
		ci.QualityCheckAllNullVoidOneMany = lm.QualityCheckAllNullVoidOneMany,
      ci.QualityCheckAllNullVoidOneValue = lm.QualityCheckAllNullVoidOneValue
WHEN NOT MATCHED THEN
    INSERT (
        DatabaseName, SchemaName, TableName, ColumnName, ColumnSort, ColumnDescription, 
        DataType, MaxLengthOrValue, MinLengthOrValue, DefaultValue, ValidationRules, CustomCastForSearch, CustomCastForCRUD,
        DistinctValueCount, IsNullable, IsPrimaryKey, IsForeignKey, IsLookupValue, IsEditable, IsFixedSetValue,
        IsDate, IsTime, IsDateTime, IsIdentity, IsInt, IsFloat, IsAssociatedToDelete, IsDeleted, IsVoid,
        IsSensitive, IsUpdateAllow, DataClassification, ComplianceTag, QualityScore, QualityRemarks,
        ParentColumnID, RestrictionsType, ColumnMetadataSyncDateTime, CreatedAt, UpdatedAt, UpdatedBy, IsDelta,QualityCheckAllNullVoidOneMany,QualityCheckAllNullVoidOneValue
    )
    VALUES (
        lm.DatabaseName, lm.SchemaName, lm.TableName, lm.ColumnName, lm.ColumnSort, lm.ColumnDescription, 
        lm.DataType, lm.MaxLengthOrValue, lm.MinLengthOrValue, lm.DefaultValue, lm.ValidationRules, lm.CustomCastForSearch, lm.CustomCastForCRUD,
        lm.DistinctValueCount, lm.IsNullable, lm.IsPrimaryKey, lm.IsForeignKey, lm.IsLookupValue, lm.IsEditable, lm.IsFixedSetValue,
        lm.IsDate, lm.IsTime, lm.IsDateTime, lm.IsIdentity, lm.IsInt, lm.IsFloat, lm.IsAssociatedToDelete, lm.IsDeleted, lm.IsVoid,
        lm.IsSensitive, lm.IsUpdateAllow, lm.DataClassification, lm.ComplianceTag, lm.QualityScore, lm.QualityRemarks,
        lm.ParentColumnID, lm.RestrictionsType, lm.ColumnMetadataSyncDateTime, GETDATE(), GETDATE(), lm.UpdatedBy, lm.IsDelta, lm.QualityCheckAllNullVoidOneMany, lm.QualityCheckAllNullVoidOneValue
    );


    -- Soft delete columns not in the latest metadata
    UPDATE ci
    SET ci.IsDeleted = 1, ci.UpdatedAt = GETDATE()
    FROM [divaconfig].[ColumnInfo] ci
    WHERE NOT EXISTS (
        SELECT 1
        FROM DivaTempLatestMetadata lm
        WHERE ci.DatabaseName = lm.DatabaseName
            AND ci.SchemaName = lm.SchemaName
            AND ci.TableName = lm.TableName
            AND ci.ColumnName = lm.ColumnName
    );


