select 
'''','''',
''Response Achiver''
,'''' AS [ResponseIsTopBoxChoice]
,'''' AS [ResponseIsBottomBoxChoice]
,'''' AS [ResponseIsAverageChoice]
,'''' AS [ResponseWeightage]
union all 
Select 
