(76, 'dbo.DMS_PostRunPatientConfig', NULL, '
CREATE PROC [dbo].[DMS_PostRunPatientConfig] AS

Begin 


IF OBJECT_ID(''dbo.DMS_SAP_Patient_Base'', ''U'')				IS NOT NULL BEGIN	DROP TABLE dbo.DMS_SAP_Patient_Base			END 
IF OBJECT_ID(''dbo.DMS_SQL_Patient_Base'', ''U'')				IS NOT NULL BEGIN	DROP TABLE dbo.DMS_SQL_Patient_Base			END
IF OBJECT_ID(''dbo.DMS_SharePoint_Patient_Base'', ''U'')		IS NOT NULL BEGIN	DROP TABLE dbo.DMS_SharePoint_Patient_Base	END
IF OBJECT_ID(''dbo.DMS_FTP_Patient_Base'', ''U'')				IS NOT NULL BEGIN	DROP TABLE dbo.DMS_FTP_Patient_Base			END


Select * INTO	DMS_SAP_Patient_Base			From DMS_SAP_Patient
Select * INTO	DMS_SQL_Patient_Base			From DMS_SQL_Patient
Select * INTO	DMS_SharePoint_Patient_Base		From DMS_SharePoint_Patient
Select * INTO	DMS_FTP_Patient_Base			From DMS_FTP_Patient


Select ''PRE Row Base Count SAP Patient'' as ''RowType'', Count(1) ''RowCount'',Count(Distinct PatientID ) ''DistinctBP''	From DMS_SAP_Patient_Base UNION
Select ''PRE Row Base Count SQL Patient'' as ''RowType'', Count(1) ''RowCount'',Count(Distinct PatientID ) ''DistinctBP''	From DMS_SQL_Patient_Base UNION
Select ''PRE Row Base Count ShP Patient'' as ''RowType'', Count(1) ''RowCount'',Count(Distinct PatientID ) ''DistinctBP''	From DMS_SharePoint_Patient_Base UNION
Select ''PRE Row Base Count FTP Patient'' as ''RowType'', Count(1) ''RowCount'',Count(Distinct PatientID ) ''DistinctBP''	From DMS_FTP_Patient_Base

--Adding a New Column to SAP
IF NOT EXISTS (
    SELECT *
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_NAME = ''DMS_SAP_Patient''
    AND COLUMN_NAME = ''PatientName''
)
BEGIN
    ALTER TABLE DMS_SAP_Patient
    ADD PatientName VARCHAR(100);
END


Update DMS_SAP_Patient
Set PatientName= ISNULL(FirstName,''NULL'')+ISNULL(LastName,''NULL'')


--Updating NULL Values of SAP

Update DMS_SAP_Patient	SET PatientName = ''NULL''		Where PatientName = ''''			OR PatientName			IS NULL
Update DMS_SAP_Patient	SET InsuranceProvider = ''NULL''	Where InsuranceProvider = ''''	OR InsuranceProvider	IS NULL
Update DMS_SAP_Patient	SET Allergies = ''NULL''			Where Allergies = ''''			OR Allergies			IS NULL
Update DMS_SAP_Patient	SET MedicalHistory = ''NULL''		Where MedicalHistory = ''''		OR MedicalHistory		IS NULL
Update DMS_SAP_Patient	SET InsuranceNumber = ''NULL''	Where InsuranceNumber = ''''		OR InsuranceNumber		IS NULL


--Adding a New Column to SQL
IF NOT EXISTS (
    SELECT *
