(78, 'dbo.sp_ui_evalsubmit', NULL, 'CREATE PROCEDURE [dbo].[sp_ui_evalsubmit]
    @SurveyID INT,
    @QuestionID INT,
    @ResponseID INT,
    @UserID INT,
    @QuestionStartDisplayDataTime DATETIME,
    @QuestionResponceSubmitedDateTime DATETIME
AS
BEGIN
    SET NOCOUNT ON;

	-- Check if record exists and FirstTimeRespoceOpenFor30DayResponceWindow is more than 30 days old
    IF EXISTS (SELECT top 1 1 FROM [LiveBit].[dbo].[FactEval]
               WHERE SurveyID = @SurveyID 
               AND QuestionID = @QuestionID 
               AND UserID = @UserID)
    BEGIN
        -- Update existing record
        UPDATE [LiveBit].[dbo].[FactEval]
        SET ResponseID = @ResponseID,
            QuestionStartDisplayDataTime = @QuestionStartDisplayDataTime,
            QuestionResponceSubmitedDateTime = @QuestionResponceSubmitedDateTime,
			RecordResponceType = ''Update'',
			BackendRecordDataTime=getdate()
        WHERE SurveyID = @SurveyID 
        AND QuestionID = @QuestionID 
        AND UserID = @UserID;
    END
    ELSE
    BEGIN
        -- Insert new record
        INSERT INTO [LiveBit].[dbo].[FactEval] 
            (SurveyID, QuestionID, ResponseID, UserID, 
             QuestionStartDisplayDataTime, QuestionResponceSubmitedDateTime,
             RecordResponceType,BackendRecordDataTime)
        VALUES 
            (@SurveyID, @QuestionID, @ResponseID, @UserID, 
             @QuestionStartDisplayDataTime, @QuestionResponceSubmitedDateTime, 
             ''Insert'', GETDATE());
    END
END


', NULL, '2024-02-02 20:13:51.823000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 03:47:42.367000', NULL),
(79, 'dbo.sp_upgraddiagrams', NULL, '
	CREATE PROCEDURE dbo.sp_upgraddiagrams
	AS
	BEGIN
		IF OBJECT_ID(N''dbo.sysdiagrams'') IS NOT NULL
			return 0;
	
		CREATE TABLE dbo.sysdiagrams
		(
			name sysname NOT NULL,
			principal_id int NOT NULL,	-- we may change it to varbinary(85)
			diagram_id int PRIMARY KEY IDENTITY,
			version int,
	
			definition varbinary(max)
			CONSTRAINT UK_principal_name UNIQUE
			(
				principal_id,
				name
			)
		);


		/* Add this if we need to have some form of extended properties for diagrams */
		/*
		IF OBJECT_ID(N''dbo.sysdiagram_properties'') IS NULL
		BEGIN
			CREATE TABLE dbo.sysdiagram_properties
			(
				diagram_id int,
				name sysname,
				value varbinary(max) NOT NULL
			)
		END
		*/

		IF OBJECT_ID(N''dbo.dtproperties'') IS NOT NULL
		begin
			insert into dbo.sysdiagrams
			(
				[name],
				[principal_id],
				[version],
				[definition]
			)
			select	 
				convert(sysname, dgnm.[uvalue]),
				DATABASE_PRINCIPAL_ID(N''dbo''),			-- will change to the sid of sa
				0,							-- zero for old format, dgdef.[version],
				dgdef.[lvalue]
			from dbo.[dtproperties] dgnm
				inner join dbo.[dtproperties] dggd on dggd.[property] = ''DtgSchemaGUID'' and dggd.[objectid] = dgnm.[objectid]	
				inner join dbo.[dtproperties] dgdef on dgdef.[property] = ''DtgSchemaDATA'' and dgdef.[objectid] = dgnm.[objectid]
				
			where dgnm.[property] = ''DtgSchemaNAME'' and dggd.[uvalue] like N''_EA3E6268-D998-11CE-9454-00AA00A3F36E_'' 
			return 2;
		end
		return 1;
	END
	', NULL, '2024-02-22 02:48:15.350000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:16:18.767000', NULL),
(80, 'dbo.LogExecutionDetails', NULL, 'CREATE PROCEDURE LogExecutionDetails
    @ProcedureName NVARCHAR(255) = NULL,  -- Only required for ''Started'' status
    @ParameterDetails NVARCHAR(MAX) = NULL,  -- Only required for ''Started'' status
    @OpenAIStepName NVARCHAR(255) = NULL,  -- Only required for ''Started'' status
    @OpenAIParameterDetails NVARCHAR(MAX) = NULL,  -- Only required for ''Started'' status
    @OpenAIPrompt NVARCHAR(MAX) = NULL,  -- Only required for ''Started'' status
    @AdditionalLoggingDetails NVARCHAR(MAX) = NULL,
    @Status NVARCHAR(50),  -- ''Started'', ''Completed'', or Error status
    @ErrorMessage NVARCHAR(MAX) = NULL,  -- Optional error message for error statuses
    @LogID INT = NULL OUTPUT,  -- Input/Output parameter for LogID
    @ExecutionGUID NVARCHAR(MAX) = NULL  -- Optional input for Execution GUID, can be blank
AS
BEGIN
    -- If no LogID is provided and status is ''Started'', insert a new log entry
    IF @LogID IS NULL AND @Status = ''Started''
    BEGIN
        -- If ExecutionGUID is not provided or blank, generate a new GUID and convert to NVARCHAR
        IF @ExecutionGUID IS NULL OR @ExecutionGUID = ''''
        BEGIN
            SET @ExecutionGUID = CAST(NEWID() AS NVARCHAR(MAX));
        END

        -- Insert log with start time and ExecutionGUID
        INSERT INTO ExecutionLog 
        (ProcedureName, StartTime, ParameterDetails, Status, OpenAIStepName, OpenAIParameterDetails, OpenAIPrompt, AdditionalLoggingDetails, ExecutionGUID)
        VALUES 
        (@ProcedureName, GETDATE(), @ParameterDetails, ''Started'', @OpenAIStepName, @OpenAIParameterDetails, @OpenAIPrompt, @AdditionalLoggingDetails, @ExecutionGUID);

        -- Capture the identity value of the inserted row (LogID)
        SET @LogID = SCOPE_IDENTITY();
    END

    -- If LogID is provided and status is ''Completed'', update the existing log with end time
    ELSE IF @LogID IS NOT NULL AND @Status = ''Completed''
    BEGIN
        UPDATE ExecutionLog
        SET EndTime = GETDATE(),
            Status = ''Completed'',
            AdditionalLoggingDetails = @AdditionalLoggingDetails
        WHERE LogID = @LogID;
    END

    -- If LogID is provided and the status is not ''Completed'' or ''Started'', treat it as an error
    ELSE IF @LogID IS NOT NULL AND @Status != ''Started'' AND @Status != ''Completed''
    BEGIN
        UPDATE ExecutionLog
        SET EndTime = GETDATE(),
            Status = ''Error'',
            ErrorMessage = @ErrorMessage,
            AdditionalLoggingDetails = @AdditionalLoggingDetails
        WHERE LogID = @LogID;
    END
    ELSE
    BEGIN
        -- Handle invalid cases where neither a valid @LogID nor a valid @Status is provided
        RAISERROR(''Invalid input: LogID or Status is missing.'', 16, 1);
    END
END;
', NULL, '2024-09-10 19:38:27.590000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:16:18.767000', NULL),
(81, 'dbo.sp_helpdiagrams', NULL, '
	CREATE PROCEDURE dbo.sp_helpdiagrams
	(
		@diagramname sysname = NULL,
		@owner_id int = NULL
	)
	WITH EXECUTE AS N''dbo''
	AS
	BEGIN
		DECLARE @user sysname
		DECLARE @dboLogin bit
		EXECUTE AS CALLER;
			SET @user = USER_NAME();
			SET @dboLogin = CONVERT(bit,IS_MEMBER(''db_owner''));
		REVERT;
		SELECT
			[Database] = DB_NAME(),
			[Name] = name,
			[ID] = diagram_id,
			[Owner] = USER_NAME(principal_id),
			[OwnerID] = principal_id
		FROM
			sysdiagrams
		WHERE
			(@dboLogin = 1 OR USER_NAME(principal_id) = @user) AND
			(@diagramname IS NULL OR name = @diagramname) AND
			(@owner_id IS NULL OR principal_id = @owner_id)
		ORDER BY
			4, 5, 1
	END
	', NULL, '2024-02-22 02:48:15.463000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:16:18.767000', NULL),
(82, 'dbo.sp_helpdiagramdefinition', NULL, '
	CREATE PROCEDURE dbo.sp_helpdiagramdefinition
	(
		@diagramname 	sysname,
		@owner_id	int	= null 		
	)
	WITH EXECUTE AS N''dbo''
	AS
	BEGIN
		set nocount on

		declare @theId 		int
		declare @IsDbo 		int
		declare @DiagId		int
		declare @UIDFound	int
	
		if(@diagramname is null)
		begin
			RAISERROR (N''E_INVALIDARG'', 16, 1);
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N''db_owner'');
		if(@owner_id is null)
			select @owner_id = @theId;
		revert; 
	
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname;
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId ))
		begin
			RAISERROR (''Diagram does not exist or you do not have permission.'', 16, 1);
			return -3
		end

		select version, definition FROM dbo.sysdiagrams where diagram_id = @DiagId ; 
		return 0
	END
	', NULL, '2024-02-22 02:48:15.467000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:16:18.767000', NULL),
