(114, 'divaconfig.LoadAllTableColumnValue', NULL, 'CREATE PROCEDURE [divaconfig].LoadAllTableColumnValue
AS

    -- Step 1: Create a physical table to store schema.table names
    IF OBJECT_ID(''[divaconfig].[TableList]'', ''U'') IS NOT NULL
        DROP TABLE [divaconfig].[TableList]; -- Drop the table if it exists
    
    CREATE TABLE [divaconfig].[TableList] (
        ID INT IDENTITY(1, 1) PRIMARY KEY, -- Unique identifier for iteration
        FullTableName NVARCHAR(256) NOT NULL -- Schema and table name
    );

    -- Step 2: Dynamically populate the table with schema.table names
    INSERT INTO [divaconfig].[TableList] (FullTableName)
    SELECT TABLE_SCHEMA + ''.'' + TABLE_NAME
    FROM INFORMATION_SCHEMA.TABLES
    WHERE TABLE_TYPE = ''BASE TABLE''; -- Adjust this filter if needed (e.g., to exclude system tables)

	Select * from [divaconfig].[TableList]

    -- Step 3: Declare variables for the loop
    DECLARE @CurrentID INT = 1; -- Start with the first ID
    DECLARE @MaxID INT; -- Store the maximum ID for the loop
    DECLARE @TableName NVARCHAR(256); -- Store the current table name

    -- Get the maximum ID from the TableList
    SELECT @MaxID = MAX(ID) FROM [divaconfig].[TableList];

    -- Step 4: Process each table in a WHILE loop
    WHILE @CurrentID <= @MaxID
    BEGIN
        -- Get the table name for the current ID
        SELECT @TableName = FullTableName
        FROM [divaconfig].[TableList]
        WHERE ID = @CurrentID;

        -- Check if a valid table name was found (to handle gaps in IDs)
        IF @TableName IS NOT NULL
        BEGIN
            -- Call the procedure for processing one table
            EXEC [divaconfig].[Load1TableColumnValue] @TableName;
        END

        -- Increment the ID
        SET @CurrentID = @CurrentID + 1;
    END;

', NULL, '2024-12-23 19:22:31.747000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:16:18.767000', NULL),
(115, 'divaconfig.sp_GetAllColumnValueData', NULL, '
CREATE PROCEDURE [divaconfig].[sp_GetAllColumnValueData]
    @SchemaTable NVARCHAR(512) -- Schema and table name in the format: schema.table
AS
BEGIN
    /*
    Description:
    - Fetches metadata for a specific table''s columns.
    - Ensures the table exists, is editable, and is not deleted.
    - Returns distinct error messages for non-existing, non-editable, or deleted tables.

    Example Usage:
    EXEC [divaconfig].[sp_GetColumnMetadata] @SchemaTable = ''dbo.MyTable'';
	 EXEC [divaconfig].[sp_GetColumnMetadata] @SchemaTable = ''divaconfig.SampleData'';
    */

    -- Variables to store schema and table name
    DECLARE @SchemaName NVARCHAR(255);
    DECLARE @TableName NVARCHAR(255);

    -- Parse Schema and Table from @SchemaTable
    SET @SchemaName = LEFT(@SchemaTable, CHARINDEX(''.'', @SchemaTable) - 1);
    SET @TableName = SUBSTRING(@SchemaTable, CHARINDEX(''.'', @SchemaTable) + 1, LEN(@SchemaTable));

    -- Check if the table exists
    IF NOT EXISTS (
        SELECT 1
        FROM [divaconfig].[TableInfo]
        WHERE [TableSchemaName] = @SchemaName
          AND [TableName] = @TableName
    )
    BEGIN
        SELECT ''The specified table ['' + @SchemaTable + ''] does not exist.'' AS ErrorMessage;
        RETURN;
    END



    -- Check if the table is deleted
    IF EXISTS (
        SELECT 1
        FROM [divaconfig].[TableInfo]
        WHERE [TableSchemaName] = @SchemaName
          AND [TableName] = @TableName
          AND [IsDeleted] = 1
    )
    BEGIN
        SELECT ''The specified table ['' + @SchemaTable + ''] is marked as deleted.'' AS ErrorMessage;
        RETURN;
    END

    -- Fetch column metadata for the specified table
    SELECT *
    FROM [divaconfig].[ColumnValue]
    WHERE [SchemaName] = @SchemaName
      AND [TableName] = @TableName

END
', NULL, '2024-12-24 04:09:36.623000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:16:18.767000', NULL),
