(138, 'dbo.GetSurveyQuestionsAndResponses', NULL, 'CREATE PROCEDURE GetSurveyQuestionsAndResponses
    @SurveyID INT
AS
BEGIN
    DECLARE @Result TABLE (
        Question NVARCHAR(MAX),
        GroupText NVARCHAR(MAX),
        Response NVARCHAR(MAX),
        Sort INT,
        ShortDescription NVARCHAR(MAX),
        LargeDescription NVARCHAR(MAX),
        IsTopBoxChoice BIT,
        IsBottomBoxChoice BIT,
        IsAverageChoice BIT,
        Weightage INT
    );

    DECLARE @QuestionID AS INT;
    DECLARE @QuestionText AS NVARCHAR(MAX);
    DECLARE @QuestionGroupText AS NVARCHAR(MAX);
    DECLARE @ResponseText AS NVARCHAR(MAX);
    DECLARE @ResponceDescriptionToAchiveThisShort AS NVARCHAR(MAX);
    DECLARE @ResponceDescriptionToAchiveThisLarge AS NVARCHAR(MAX);
    DECLARE @ResponseSort AS INT;
    DECLARE @ResponseIsTopBoxChoice AS BIT;
    DECLARE @ResponseIsBottomBoxChoice AS BIT;
    DECLARE @ResponseIsAverageChoice AS BIT;
    DECLARE @ResponseWeightage AS INT;

    DECLARE question_cursor CURSOR FOR
    SELECT q.QuestionID, q.QuestionText, q.QuestionGroupText
    FROM [dbo].[Survey] s
    INNER JOIN [dbo].[Question] q ON q.QuestionSurveyID = s.SurveyID
    WHERE s.SurveyID = @SurveyID
    ORDER BY q.QuestionSort;

    OPEN question_cursor;
    FETCH NEXT FROM question_cursor INTO @QuestionID, @QuestionText, @QuestionGroupText;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE response_cursor CURSOR FOR
        SELECT 
            r.ResponseText,
            r.ResponceDescriptionToAchiveThisShort,
            r.ResponceDescriptionToAchiveThisLarge,
            r.ResponseSort,
            r.ResponseIsTopBoxChoice,
            r.ResponseIsBottomBoxChoice,
            r.ResponseIsAverageChoice,
            r.ResponseWeightage
        FROM [dbo].[Response] r
        WHERE r.ResponseQuestionID = @QuestionID
        ORDER BY r.ResponseSort;

        OPEN response_cursor;
        FETCH NEXT FROM response_cursor INTO @ResponseText, @ResponceDescriptionToAchiveThisShort, @ResponceDescriptionToAchiveThisLarge,
                                             @ResponseSort, @ResponseIsTopBoxChoice, @ResponseIsBottomBoxChoice, @ResponseIsAverageChoice,
                                             @ResponseWeightage;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            INSERT INTO @Result (Question, GroupText, Response, Sort, ShortDescription, LargeDescription,
                                 IsTopBoxChoice, IsBottomBoxChoice, IsAverageChoice, Weightage)
            VALUES (@QuestionText, @QuestionGroupText, @ResponseText, @ResponseSort, @ResponceDescriptionToAchiveThisShort,
                    @ResponceDescriptionToAchiveThisLarge, @ResponseIsTopBoxChoice, @ResponseIsBottomBoxChoice,
                    @ResponseIsAverageChoice, @ResponseWeightage);

            FETCH NEXT FROM response_cursor INTO @ResponseText, @ResponceDescriptionToAchiveThisShort, @ResponceDescriptionToAchiveThisLarge,
                                                 @ResponseSort, @ResponseIsTopBoxChoice, @ResponseIsBottomBoxChoice,
                                                 @ResponseIsAverageChoice, @ResponseWeightage;
        END

        CLOSE response_cursor;
        DEALLOCATE response_cursor;

        FETCH NEXT FROM question_cursor INTO @QuestionID, @QuestionText, @QuestionGroupText;
    END

    CLOSE question_cursor;
    DEALLOCATE question_cursor;

    SELECT * FROM @Result;
END
', NULL, '2024-04-19 11:20:24.903000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:20:14.063000', NULL),
(139, 'divaconfig.LoadStoredProcedures', NULL, 'CREATE PROC divaconfig.LoadStoredProcedures
As
--CREATE TABLE divaconfig.StoredProcedures (
--    ProcedureID INT IDENTITY PRIMARY KEY,
--    ProcedureName VARCHAR(255) NOT NULL,
--    ProcedureDescription VARCHAR(500),
--    ProcedureDefinition NVARCHAR(MAX), -- Increased size for longer definitions
--    ProcedureCreatedBy VARCHAR(100),
--    ProcedureCreatedDate DATETIME DEFAULT GETDATE(),
--    ProcedureIsManualOnly BIT NULL,
--    ProcedureIsIngestionOnly BIT NULL,
--    ProcedureCategory1 VARCHAR(100) NULL,
--    ProcedureCategory2 VARCHAR(100) NULL,
--    ProcedureCategory3 VARCHAR(100) NULL,
--    ProcedureCategory4 VARCHAR(100) NULL,
--    ProcedureCategory5 VARCHAR(100) NULL,
--    Type2Active BIT NOT NULL DEFAULT 1,        -- Type 2 active flag
--    Type2StartDate DATETIME DEFAULT GETDATE(), -- Type 2 start date
--    Type2EndDate DATETIME NULL                 -- Type 2 end date
--);


-- Insert stored procedure metadata dynamically into divaconfig.StoredProcedures
--Truncate From divaconfig.StoredProcedures
INSERT INTO divaconfig.StoredProcedures (
    ProcedureName,
    ProcedureDescription,
    ProcedureDefinition,
    ProcedureCreatedBy,
    ProcedureCreatedDate,
    ProcedureIsManualOnly,
    ProcedureIsIngestionOnly,
    ProcedureCategory1,
    ProcedureCategory2,
    ProcedureCategory3,
    ProcedureCategory4,
    ProcedureCategory5
)
SELECT
    SCHEMA_NAME(p.schema_id) + ''.'' + p.name AS ProcedureName, -- Full procedure name with schema
    NULL AS ProcedureDescription, -- Placeholder, can be updated manually
    OBJECT_DEFINITION(p.object_id) AS ProcedureDefinition, -- Retrieves the procedure definition
    SUSER_SNAME(p.principal_id) AS ProcedureCreatedBy, -- Owner of the procedure
    p.create_date AS ProcedureCreatedDate, -- Creation date
    NULL AS ProcedureIsManualOnly, -- Placeholder, to be updated based on business logic
    NULL AS ProcedureIsIngestionOnly, -- Placeholder, to be updated based on business logic
    NULL AS ProcedureCategory1, -- Placeholder, to be updated manually or dynamically
    NULL AS ProcedureCategory2, -- Placeholder, to be updated manually or dynamically
    NULL AS ProcedureCategory3, -- Placeholder, to be updated manually or dynamically
    NULL AS ProcedureCategory4, -- Placeholder, to be updated manually or dynamically
    NULL AS ProcedureCategory5 -- Placeholder, to be updated manually or dynamically
FROM
    sys.procedures p
WHERE
    p.is_ms_shipped = 0; -- Exclude system-stored procedures


--CREATE TABLE divaconfig.StoredProcedureParameters (
--    ParameterID INT IDENTITY PRIMARY KEY,
--    ProcedureID INT NOT NULL, -- Foreign key to StoredProcedures table
--    ParameterName VARCHAR(255) NOT NULL,
--    ParameterDataType NVARCHAR(50),
--    ParameterIsOptional BIT DEFAULT 0,
--    ParameterDefaultValue VARCHAR(255) NULL,
--    ParameterDefaultDynamicValue VARCHAR(255) NULL,
--    Type2Active BIT NOT NULL DEFAULT 1,        -- Type 2 active flag
--    Type2StartDate DATETIME DEFAULT GETDATE(), -- Type 2 start date
--    Type2EndDate DATETIME NULL                 -- Type 2 end date
--);

--Truncate table divaconfig.StoredProcedureParameters

-- Loop through all stored procedures and populate StoredProcedureParameters dynamically
INSERT INTO divaconfig.StoredProcedureParameters (
    ProcedureID,
    ParameterName,
    ParameterDataType,
    ParameterIsOptional,
    ParameterDefaultValue,
    ParameterDefaultDynamicValue
)
SELECT
    sp.ProcedureID,
    p.name AS ParameterName,
    TYPE_NAME(p.user_type_id) AS ParameterDataType,
    CASE WHEN p.is_output = 1 THEN 1 ELSE 0 END AS ParameterIsOptional, -- Treat OUTPUT parameters as optional
    NULL AS ParameterDefaultValue, -- SQL Server does not store default values directly
    NULL AS ParameterDefaultDynamicValue -- Placeholder for dynamic default values
FROM
    sys.procedures procs
INNER JOIN
    sys.parameters p ON procs.object_id = p.object_id
INNER JOIN
    divaconfig.StoredProcedures sp ON sp.ProcedureName = SCHEMA_NAME(procs.schema_id) + ''.'' + procs.name
WHERE
    procs.is_ms_shipped = 0; -- Exclude system-stored procedures


INSERT INTO divaconfig.StoredProcedureAccess (
    ProcedureID,
    UserID,
    HasExecuteAccess,
    Type2Active,
    Type2StartDate
)
SELECT 
    sp.ProcedureID,
    u.UserID,
    1 AS HasExecuteAccess, -- Grant execute access
    1 AS Type2Active, -- Active permission
    GETDATE() AS Type2StartDate -- Current date
FROM 
    divaconfig.StoredProcedures sp
CROSS JOIN 
    dbo.[User] u; -- Combine all procedures with all users


/*
CREATE TABLE divaconfig.StoredProcedureExecutionLog (
    ProcedureLogID INT IDENTITY PRIMARY KEY,
    ProcedureID INT NULL ,
	ProcedureTabID INT NULL ,
    ProcedureExecutedBy NVARCHAR(255) NOT NULL,
    ProcedureExecutionStart DATETIME DEFAULT GETDATE(),
	ProcedureExecutionEnd DATETIME ,
    ProcedureParametersUsed NVARCHAR(MAX),
    ProcedureExecutionStatus NVARCHAR(50),
    ProcedureErrorMessage NVARCHAR(MAX)
);
CREATE TABLE divaconfig.ProcedureTabMapping (
    MappingID INT IDENTITY ,
    ProcedureID INT NOT NULL ,
    SubTabID INT NOT NULL ,
    ProcedureTabMappingDescription NVARCHAR(500),
    ProcedureTabMappingCreatedDate DATETIME DEFAULT GETDATE(),
	Type2Active BIT NOT NULL DEFAULT 1,        -- Type 2 active flag
    Type2StartDate DATETIME DEFAULT GETDATE(), -- Type 2 start date
    Type2EndDate DATETIME NULL                 -- Type 2 end date
);

CREATE TABLE divaconfig.StoredProcedureAccess (
    AccessID INT IDENTITY ,
    ProcedureID INT NULL,
    UserID INT NULL,
    HasExecuteAccess BIT DEFAULT 0,
	Type2Active BIT NOT NULL DEFAULT 1,        -- Type 2 active flag
    Type2StartDate DATETIME DEFAULT GETDATE(), -- Type 2 start date
    Type2EndDate DATETIME NULL                 -- Type 2 end date
);

*/', NULL, '2025-01-15 09:46:33.727000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:20:14.063000', NULL),
(140, 'divaconfig.sp_DynamicCRUDold', NULL, '
CREATE PROCEDURE [divaconfig].[sp_DynamicCRUD]
    @InputSchemaTable NVARCHAR(256), -- Format: ''schema.table''
    @InputOperationType NVARCHAR(10), -- Expected: ''Create''
    @InputCSVValues NVARCHAR(MAX) NULL -- CSV value list
AS

--Declare @InputSchemaTable NVARCHAR(256), -- Format: ''schema.table''
--    @InputOperationType NVARCHAR(10), -- Expected: ''Create''
--    @InputCSVValues NVARCHAR(MAX) -- CSV value list

	Declare @SchemaTable NVARCHAR(256), -- Format: ''schema.table''
    @OperationType NVARCHAR(10), -- Expected: ''Create''
    @CSVValues NVARCHAR(MAX), -- CSV value list
	@SQLRead NVARCHAR(MAX)
	--SET @SchemaTable =''divaconfig.SampleData''
	--SET @OperationType=''Read''
	--SET @CSVValues=''99$|@MasterNameSampleColumn1$|@MasterValue1$|@MasterDisplayTextDescription1$|@MasterDescriptionnvarchar$|@1$|@NULL$|@14:45:301$|@NULL$|@98$|@1.0$|@99$|@NULL$|@null$|@10$|@15.5$|@1$|@NULL$|@NULL''
    SET @CSVValues = REPLACE(@CSVValues, ''$|@'', ''|'');
	SET @SchemaTable =@InputSchemaTable
	SET @OperationType=@InputOperationType
	SET @CSVValues= @InputCSVValues
    SET @CSVValues = REPLACE(@CSVValues, ''$|@'', ''|'');
    DECLARE @Schema NVARCHAR(128), @Table NVARCHAR(128), @Query NVARCHAR(MAX);
    DECLARE @ColumnMetadata TABLE (
        ColumnName NVARCHAR(128),
        SortOrder INT,
        CustomCastForCRUD NVARCHAR(MAX),
        IsNullable BIT,
		IsIdentity bit
    );
    -- Split Schema and Table
    SET @Schema = LEFT(@SchemaTable, CHARINDEX(''.'', @SchemaTable) - 1);
    SET @Table = RIGHT(@SchemaTable, LEN(@SchemaTable) - CHARINDEX(''.'', @SchemaTable));

	--Select @Schema,@Table

	IF(@OperationType=''Read'')
	BEGIN 

	SET @SQLRead = N''SELECT * FROM '' + QUOTENAME(@Schema) + ''.'' + QUOTENAME(@Table)
	-- Print the SQL to verify
	PRINT @SQLRead

	EXEC sp_executesql @SQLRead

	END
	IF(@OperationType=''Create'')
	BEGIN

	IF OBJECT_ID(''dbo.DivaTempInsert'', ''U'') IS NOT NULL
    DROP TABLE dbo.DivaTempInsert;



	-- Use SELECT INTO to dynamically create the table with all data types
	SELECT TOP 0 *
	INTO dbo.DivaTempInsert
	FROM [divaconfig].[ColumnInfo];

	-- Enable IDENTITY_INSERT for the table
	SET IDENTITY_INSERT dbo.DivaTempInsert ON;

    -- Get column metadata ordered by SortOrder
    INSERT Into dbo.DivaTempInsert 
	(ColumnID,DatabaseName,SchemaName,TableName,ColumnName,ColumnSort,ColumnDescription,DataType,MaxLengthOrValue,MinLengthOrValue,DefaultValue
	,ValidationRules,CustomCastForSearch,CustomCastForCRUD,DistinctValueCount,IsNullable,IsPrimaryKey,IsForeignKey,IsLookupValue,IsEditable
	,IsFixedSetValue,IsDate,IsTime,IsDateTime,IsIdentity,IsInt,IsFloat,IsAssociatedToDelete,IsDeleted,IsVoid,IsSensitive,IsUpdateAllow,IsDelta
	,IsLockFromBackend,IsLockFromFrontEnd,TextualDataType,DataClassification,ComplianceTag,QualityCheckAllNullVoidOneMany
	,QualityCheckAllNullVoidOneValue,QualityScore,QualityRemarks,ParentColumnID,RestrictionsType,ColumnMetadataSyncDateTime,CreatedAt,UpdatedAt,UpdatedBy)
	Exec [divaconfig].[sp_GetColumnMetadata] @SchemaTable;

	--Select * from dbo.DivaTempInsert 

		-- Retrieve Metadata Ordered by SortOrder
		-- Insert column metadata into @ColumnMetadata table
		INSERT INTO @ColumnMetadata (ColumnName, SortOrder, CustomCastForCRUD, IsNullable,IsIdentity)
		SELECT 
			ColumnName,
			ColumnSort,
			CustomCastForCRUD,
			IsNullable,
			IsIdentity
		FROM dbo.DivaTempInsert
		WHERE CustomCastForCRUD IS NOT NULL
		ORDER BY ColumnSort;

		-- Drop temporary table if it exists
		IF OBJECT_ID(''dbo.DivaTempInsertValues'', ''U'') IS NOT NULL
			DROP TABLE dbo.DivaTempInsertValues;

		-- Parse the CSV values and map to metadata
		;WITH ParsedCSV AS (
			SELECT 
				value,
				ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS SortOrder
			FROM STRING_SPLIT(@CSVValues, ''|'') -- Use ''|'' as the delimiter
		)
		-- Map CSV values to column metadata and generate casted values
		SELECT 
			cm.ColumnName,
			REPLACE(cm.CustomCastForCRUD, cm.ColumnName, ''''''''+p.value+'''''''')
			AS CastedValue
		INTO dbo.DivaTempInsertValues 
		FROM ParsedCSV p
		JOIN @ColumnMetadata cm ON p.SortOrder = cm.SortOrder
		Where cm.IsIdentity <>1
		
				
				update DivaTempInsertValues
				SET CastedValue = NULL
				Where CastedValue like ''%null%''
				Select * from DivaTempInsertValues

-- Generate the final INSERT INTO query dynamically
DECLARE @InsertColumns NVARCHAR(MAX), @InsertValues NVARCHAR(MAX);

-- Construct column names for the INSERT statement
SELECT @InsertColumns = STRING_AGG(ColumnName, '', '')
FROM dbo.DivaTempInsertValues;

-- Construct values for the INSERT statement
SELECT @InsertValues = STRING_AGG(CastedValue, '', '')
FROM dbo.DivaTempInsertValues;

-- Final INSERT query
SET @Query = ''
INSERT INTO '' + @Schema + ''.'' + @Table + ''
('' + @InsertColumns + '')
VALUES
('' + @InsertValues + '');'';

-- Output the query for debugging
PRINT @Query;

-- Uncomment below to execute the query
--EXEC sp_executesql @Query;

END


', NULL, '2024-12-24 05:54:11.273000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '2025-02-07 04:20:14.063000', NULL),
